import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"LP 对偶","description":"","frontmatter":{"title":"LP 对偶","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lp-duality.md","filePath":"cs/lp-duality.md","lastUpdated":1789023840000}'),h={name:"cs/lp-duality.md"};function _(m,a,u,f,x,E){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="lp-对偶" tabindex="-1">LP 对偶 <a class="header-anchor" href="#lp-对偶" aria-label="Permalink to &quot;LP 对偶&quot;">​</a></h1><div class="epigraph"><p>每个约束一张对偶变量；弱对偶给目标上界，强对偶在最优处相等，互补松弛刻画最优基。</p><footer>—— 据 Dantzig, 1963；von Neumann 的对偶观察；CLRS 第 29 章整理</footer></div><p>上一课<a href="/cs/simplex">单纯形</a>在原问题上转轴。缺口是对偶 LP：\\(\\min b^\\top y\\)，\\(A^\\top y\\ge c\\)，\\(y\\ge 0\\)（形式随标准形变）。弱对偶：\\(c^\\top x\\le b^\\top y\\) 对任意可行对。强对偶：都可行则最优值相等（有限时）。不重写转轴表。后课整数规划对偶间隙可正。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原 \\(\\max c^\\top x\\)，\\(Ax\\le b\\)，\\(x\\ge 0\\)。对偶 \\(\\min b^\\top y\\)，\\(A^\\top y\\ge c\\)，\\(y\\ge 0\\)。最大流最小割是对偶的组合影子。匹配顶标（KM）是指派问题的对偶。缺口是这张表，不是再跑单纯形。</p><p>无界原问题 \\(\\Rightarrow\\) 对偶不可行，反之亦然（弱对偶）。</p><h3 id="不是拉格朗日乘数课的重写" tabindex="-1">不是拉格朗日乘数课的重写 <a class="header-anchor" href="#不是拉格朗日乘数课的重写" aria-label="Permalink to &quot;不是拉格朗日乘数课的重写&quot;">​</a></h3><p>对偶可从拉格朗日来，本课认 LP 教科书构造：约束 \\(\\leftrightarrow\\) 变量，右端 \\(\\leftrightarrow\\) 目标。内点法用障碍，后课。</p><p><span class="marginnote">CLRS 29.4–29.5。最大流最小割、König 是强对偶实例。后课分支定界：整数使对偶间隙出现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写出对偶。用弱对偶证界。用互补松弛检查 \\((x,y)\\)：松弛约束对应零对偶，正变量对应紧约束。</p>',11)),(e(),s(c,null,{default:r(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E5%8E%9F%E5%8F%AF%E8%A1%8C%20x%22%5D%20--%3E%20W%5B%22c%5ET%20x%20%E2%89%A4%20b%5ET%20y%22%5D%0A%20%20DU%5B%22%E5%AF%B9%E5%81%B6%E5%8F%AF%E8%A1%8C%20y%22%5D%20--%3E%20W%0A%20%20W%20--%3E%20STR%5B%22%E6%9C%80%E4%BC%98%E5%88%99%E7%9B%B8%E7%AD%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>单纯形最优基同时给对偶解。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>弱对偶：把约束加权 \\(y\\) 与目标比。强对偶：多面体几何或单纯形终止时检验数给出 \\(y\\)。与 KM：顶标即 \\(y\\)，相等子图即互补松弛。与最小割：割容量是对偶可行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证强对偶的 Farkas 全文。非线性对偶不写。后课默认：LP 有强对偶；组合算法常是原–对偶。下一课整数规划与分支定界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>弱对偶始终给界；强对偶最优相等。</li><li>互补松弛连接原与对偶。</li><li>流–割、顶标是实例。</li><li>出处：Dantzig, 1963；CLRS 第 29 章。</li></ul>',7))])}const A=i(h,[["render",_]]);export{b as __pageData,A as default};
